//! Vortex-Ai-Chat browser UI (Leptos CSR → WebAssembly).
//! All application logic runs as Rust compiled to WASM; the only "JS" is the
//! wasm-bindgen glue generated by the Rust toolchain.

pub mod api;
pub mod chat;
pub mod diagnostics;
pub mod jobs;
pub mod markdown;
mod model_picker;
mod session_usage;
pub mod settings_ui;
pub mod sidebar;
pub mod sse;
pub mod state;
pub mod tasks;

use crate::sidebar::Sidebar;
use leptos::prelude::*;
use leptos::task::spawn_local;
use state::{AppCtx, Tab};

#[component]
pub fn App() -> impl IntoView {
    let ctx = AppCtx::new();
    provide_context(ctx);

    // Load settings + capabilities first (drives theme + honest state).
    let ctx_boot = ctx;
    spawn_local(async move {
        match api::settings().await {
            Ok(s) => {
                crate::state::apply_theme(s.theme);
                ctx_boot.replace_settings(s);
            }
            Err(e) => ctx_boot
                .error_banner
                .set(Some(format!("could not load settings: {e}"))),
        }
        match api::health().await {
            Ok(c) => ctx_boot.capabilities.set(Some(c)),
            Err(e) => ctx_boot
                .error_banner
                .set(Some(format!("server unreachable: {e}"))),
        }
        if let Ok(convs) = api::conversations("").await {
            ctx_boot.conversations.set(convs);
        }
        if let Ok(apprs) = api::approvals().await {
            ctx_boot
                .approvals
                .set(sse::filter_resolved_approvals(apprs));
        }
    });

    // Poll pending approvals so requests raised by sub-agents appear promptly.
    // Responses are filtered through the session-resolved set: a poll that
    // was already in flight when an approval got resolved must not put the
    // resolved card back on screen (P12).
    let ctx_poll = ctx;
    set_interval(
        move || {
            let ctx = ctx_poll;
            spawn_local(async move {
                if let Ok(apprs) = api::approvals().await {
                    ctx.approvals.set(sse::filter_resolved_approvals(apprs));
                }
            });
        },
        std::time::Duration::from_secs(5),
    );

    // Streaming-bubble throttle (P12): markdown + syntax highlighting re-run
    // on `stream_display`, which mirrors `stream_text` at most every 125 ms
    // (≤8 renders/s instead of one per SSE delta). App-level interval: views
    // come and go with tab switches, this lives for the session.
    let ctx_throttle = ctx;
    set_interval(
        move || {
            let next = ctx_throttle.stream_text.get_untracked();
            if ctx_throttle.stream_display.get_untracked() != next {
                ctx_throttle.stream_display.set(next);
            }
        },
        std::time::Duration::from_millis(125),
    );

    Effect::new(move || {
        ctx.current.track();
        session_usage::reload(ctx);
    });

    let narrow = RwSignal::new(false);
    let update_narrow = move || {
        let matches = window()
            .match_media("(max-width: 768px)")
            .ok()
            .flatten()
            .is_some_and(|query| query.matches());
        narrow.set(matches);
        if !matches && ctx.sidebar_open.get_untracked() {
            ctx.sidebar_open.set(false);
        }
    };
    update_narrow();
    let resize = window_event_listener(leptos::ev::resize, move |_| update_narrow());
    on_cleanup(move || resize.remove());
    let drawer_open = move || narrow.get() && ctx.sidebar_open.get();
    let menu_button = NodeRef::<leptos::html::Button>::new();
    Effect::new(move |previous| {
        let open = drawer_open();
        if previous != Some(open) {
            request_animation_frame(move || {
                if open && untrack(drawer_open) {
                    use wasm_bindgen::JsCast;
                    if let Some(button) = document()
                        .get_element_by_id("new-conversation")
                        .and_then(|el| el.dyn_into::<web_sys::HtmlElement>().ok())
                    {
                        let _ = button.focus();
                    }
                } else if previous == Some(true) && narrow.get_untracked() && !untrack(drawer_open)
                {
                    if let Some(button) = menu_button.get_untracked() {
                        let _ = button.focus();
                    }
                }
            });
        }
        open
    });
    let escape_listener =
        window_event_listener(leptos::ev::keydown, move |ev: web_sys::KeyboardEvent| {
            if ev.key() == "Escape" && untrack(drawer_open) && !ev.default_prevented() {
                ev.prevent_default();
                ctx.sidebar_open.set(false);
            }
        });
    on_cleanup(move || escape_listener.remove());

    view! {
        <div class="app">
            <Sidebar />
            <Show when=drawer_open>
                <div class="sidebar-backdrop" on:click=move |_| ctx.sidebar_open.set(false)></div>
            </Show>
            <main class="main" inert=drawer_open>
                <header class="topbar">
                    <button class="icon-btn menu-btn" node_ref=menu_button
                        aria-label="Toggle conversations sidebar"
                        aria-expanded=drawer_open
                        aria-controls="conversation-sidebar"
                        title="Conversations"
                        on:click=move |_| ctx.sidebar_open.update(|open| *open = !*open)>"☰"</button>
                    <div class="tabs" role="tablist">
                        <button class=tab_class(ctx, Tab::Chat)
                            on:click=move |_| ctx.tab.set(Tab::Chat)>"Chat"</button>
                        <button class=tab_class(ctx, Tab::Tasks)
                            on:click=move |_| ctx.tab.set(Tab::Tasks)>
                            {move || {
                                let pending = ctx.approvals.get().len();
                                if pending > 0 { format!("Tasks ({pending})") } else { "Tasks".to_string() }
                            }}
                        </button>
                        <button class=tab_class(ctx, Tab::Jobs)
                            on:click=move |_| ctx.tab.set(Tab::Jobs)>
                            {move || {
                                let parked = ctx.jobs_inbox.get().len();
                                if parked > 0 { format!("Jobs ({parked})") } else { "Jobs".to_string() }
                            }}
                        </button>
                        <button class=tab_class(ctx, Tab::Settings)
                            on:click=move |_| ctx.tab.set(Tab::Settings)>"Settings"</button>
                    </div>
                    <div class="mode-select" title="Tools available to the assistant for the next message">
                        <label for="mode">"Mode"</label>
                        <select id="mode" aria-label="Mode" on:change=move |ev| {
                            let v = event_target_value(&ev);
                            if let Ok(m) = serde_json::from_value::<vortex_types::Mode>(
                                serde_json::Value::String(v),
                            ) {
                                ctx.mode.set(m);
                            }
                        }>
                            {move || {
                                let m = ctx.mode.get();
                                view! {
                                    <option value="chat" selected={m == vortex_types::Mode::Chat}>"Chat"</option>
                                    <option value="research" selected={m == vortex_types::Mode::Research}>"Research"</option>
                                    <option value="coding" selected={m == vortex_types::Mode::Coding}>"Coding"</option>
                                    <option value="browser" selected={m == vortex_types::Mode::Browser}>"Browser"</option>
                                    <option value="agent" selected={m == vortex_types::Mode::Agent}>"Agent"</option>
                                }
                            }}
                        </select>
                    </div>
                    <ThemeToggle />
                </header>
                <Show when=move || ctx.error_banner.get().is_some()>
                    <div class="banner error">
                        {move || ctx.error_banner.get().unwrap_or_default()}
                    </div>
                </Show>
                <div class="content">
                    {move || match ctx.tab.get() {
                        Tab::Chat => view! { <chat::ChatView /> }.into_any(),
                        Tab::Tasks => view! { <tasks::TasksView /> }.into_any(),
                        Tab::Jobs => view! { <jobs::JobsView /> }.into_any(),
                        Tab::Settings => view! { <settings_ui::SettingsView /> }.into_any(),
                    }}
                </div>
            </main>
            <Show when=move || ctx.toast.get().is_some()>
                <div class="toast" role="status">{move || ctx.toast.get().unwrap_or_default()}</div>
            </Show>
        </div>
    }
}

fn tab_class(ctx: AppCtx, tab: Tab) -> impl Fn() -> String + Clone {
    move || {
        if ctx.tab.get() == tab {
            "tab active".to_string()
        } else {
            "tab".to_string()
        }
    }
}

#[component]
fn ThemeToggle() -> impl IntoView {
    let ctx = use_context::<AppCtx>().expect("ctx provided");
    view! {
        <button class="icon-btn"
            title="Toggle theme"
            on:click=move |_| {
                let s = ctx.settings.get_untracked();
                let new_theme = match s.as_ref().map(|s| s.theme) {
                    Some(vortex_types::Theme::Light) => vortex_types::Theme::Dark,
                    _ => vortex_types::Theme::Light,
                };
                crate::state::apply_theme(new_theme);
                if let Some(mut s) = s {
                    s.theme = new_theme;
                    let ctx = ctx;
                    spawn_local(async move {
                        if let Ok(saved) = api::save_settings(&s).await {
                            ctx.replace_settings(saved);
                        }
                    });
                }
            }>
            {move || {
                match ctx.settings.get().map(|s| s.theme) {
                    Some(vortex_types::Theme::Light) => "☾".to_string(),
                    _ => "☀".to_string(),
                }
            }}
        </button>
    }
}
